135	     * @param multiplyProbability Base probability of spreading to a free adjacent cell.
136	     * @param optimalBreedingFactor Multiplier used in rain and sunny weather.
137	     */
138	    protected void growAndMultiply(List<Actor> newPlants,
139	                                   Weather weather,
140	                                   DayState dayState,
141	                                   int maxAge,
142	                                   double multiplyProbability,
143	                                   double optimalBreedingFactor)
144	    {
145	        if(dayState == DayState.NIGHT) {
146	            return;
147	        }
148	
149	        grow(maxAge);
150	        if(!isAlive()) {
151	            return;
152	        }
153	
154	        if(isOptimalGrowingWeather(weather)) {
155	            multiply(optimalBreedingFactor * multiplyProbability, newPlants);
156	            return;
157	        }
158	
159	        multiply(multiplyProbability, newPlants);
160	    }
161	
162	    /**
163	     * Weather that improves plant spreading.
164	     *
165	     * @param weather The current weather.
166	     * @return true for favorable weather.
167	     */
168	    private boolean isOptimalGrowingWeather(Weather weather)
169	    {
170	        return weather == Weather.RAIN || weather == Weather.SUNNY;
171	    }
